  foreach(var p in profiles){foreach(var l in new[]{WorkerLanguage.KO,WorkerLanguage.EN,WorkerLanguage.VI}){phrases.Add(("WorkerCard/"+p.workerId+"/"+l,p.Name(l)));phrases.Add(("WorkerDescription/"+p.workerId+"/"+l,p.Description(l)));}phrases.Add(("WorkerTechnicalLabels",p.workerId+" "+p.roleCode+" "+p.icon+" "+p.Pattern));foreach(var r in new WorkerAccidentRoleAdapter(repository).Matches(p).Take(5))phrases.Add(("WorkerRoleAccidentEvidence/"+p.workerId,r.accidentId+" / "+r.title));}
