   if(pair.characters.Length==0)continue;string path=AssetDatabase.GetAssetPath(pair.font);string before=Sha(path);var old=new HashSet<uint>(pair.font.characterTable.Select(c=>c.unicode));pair.font.TryAddCharacters(pair.characters,out uint[] absent);if(absent!=null&&absent.Length>0)throw new Exception("Allowed Worker font cannot add "+string.Join(",",absent.Select(v=>"U+"+v.ToString("X4"))));
