   changes.Add(new{path,beforeSha256=before,afterSha256=Sha(path),added=pair.font.characterTable.Where(c=>!old.Contains(c.unicode)).Select(c=>new{character=char.ConvertFromUtf32((int)c.unicode),unicode="U+"+c.unicode.ToString("X4")}),sourceFont=AssetDatabase.GetAssetPath(pair.font.sourceFontFile)});
  }
  foreach(var p in phrases)if(!primary.HasCharacters(p.text,out uint[] absent,true,false))throw new Exception("Remaining Worker UI glyphs "+p.screen+" "+string.Join(",",absent));File.WriteAllText(Path.Combine(Evidence,"WorkerFontChanges.json"),JsonConvert.SerializeObject(changes,Formatting.Indented));File.WriteAllText(Path.Combine(Evidence,"WorkerUIUsedPhrases.json"),JsonConvert.SerializeObject(phrases.Select(p=>new{p.screen,p.text}),Formatting.Indented));
 }
